def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 4 else 35.0))

    slots = supply / float(WATER_REQ)
    pressure = len(alive_opponents) + 1 - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        bid = max(95.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        if pressure >= 2.5:
            bid = max(82.0, avg_prev + 3.0)
        elif pressure >= 1.5:
            bid = max(68.0, avg_prev * 0.72)
        else:
            bid = 44.0
    else:
        if supply >= 24:
            bid = 18.0
        elif supply >= 21:
            bid = 24.0
        elif supply >= 18:
            bid = 34.0
        else:
            bid = 48.0

        if pressure >= 2.5:
            bid = max(bid, min(72.0, avg_prev * 0.62 + 4.0))
        elif pressure >= 1.5:
            bid = max(bid, min(56.0, avg_prev * 0.48 + 3.0))

    if urgent_opp >= 2 and hp > 4 and no_water == 0:
        bid *= 0.88
    if rich_opp >= 2 and pressure >= 1.5:
        bid *= 1.08
    if day >= 8 and hp > 5 and budget < DAILY_SALARY * 2:
        bid *= 0.9
    if day >= 8 and (hp <= 4 or no_water >= 1):
        bid *= 1.15

    min_safe = 12.0 if hp > 5 and no_water == 0 else 22.0
    bid = max(min_safe, bid)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o is None:
            continue
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        bid = DAILY_SALARY * 0.4
        return float(min(my_budget, bid))

    # Yesterday reaction: use only previous_trace
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        if pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt.get('bid')))
            except Exception:
                pass
        if pt.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(pt.get('hp_after')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_hp_after = min(prev_hp_after) if prev_hp_after else my_hp

    # Supply pressure heuristic
    # If supply is tight (near 15), we must secure water; if abundant (near 25), we can bid less.
    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    tightness = max(0.0, min(1.0, tightness))

    # Base bid: moderate, scaled by tightness
    base = DAILY_SALARY * (0.40 + 0.25 * tightness)

    # Escalate if my hp is low or I've gone without water
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.10 * tightness)

    # Exploit opponent behavior: if someone previously bid very high, they likely were fighting for survival.
    # Match/beat slightly when their pressure was high.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp > 3.0:
            base = max(base, highest_prev_bid + 5.0)
        else:
            base = max(base, highest_prev_bid + 15.0)

    # If lowest hp_after among survivors was already low, they may continue to bid to avoid death.
    if lowest_prev_hp_after <= 3.0:
        base = max(base, DAILY_SALARY * (0.65 + 0.15 * tightness))

    # Budget safety cap
    # Avoid overcommitting: keep some budget for later days.
    # If budget is low, bid up to what we can.
    reserve = DAILY_SALARY * 0.2
    max_affordable = max(0.0, my_budget - reserve)
    if max_affordable <= 0.0:
        return float(min(my_budget, DAILY_SALARY * 0.95))

    bid = min(base, max_affordable, my_budget)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.55

    remaining_days = EPISODE_DAYS - current_day
    if my_status['hp'] <= 2 or remaining_days <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 3 and remaining_days > 2:
                bid = max(bid, highest_prev_bid * 0.98)
            else:
                bid = max(bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid = max(bid, highest_prev_bid + 2)
        else:
            bid = max(bid, highest_prev_bid + 1)

    num_potential_winners = int(current_supply // WATER_REQ)
    num_competitors = len(alive_opponents) + 1

    if num_competitors > num_potential_winners and num_potential_winners > 0:
        if my_status['hp'] <= 3:
            bid = max(bid, DAILY_SALARY * 0.98)
        else:
            bid = max(bid, DAILY_SALARY * 0.8)

    final_bid = min(my_status['budget'], bid)
    final_bid = max(1.0, final_bid)

    return final_bid

